\label{thm:intro-classification}
Fix $p>0$ and $D\ge0$.  Up to nonsingular quadratic suspension, the isolated germs $f$
with $\operatorname{Rmod}(f)\le D$ are covered by finitely many algebraic families
$F_i(x,t)$, with $t\in T_i$, such that:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item $\dim T_i\le D$, the number of residual variables is bounded in terms of $p,D$,
and the degrees of the representatives are bounded in terms of $p,D$;
\item every stable right-equivalence class occurs;
\item each stable class occurs at only finitely many points of each $T_i$.
\end{enumerate}
The families may be refined so that Milnor number and right modality are constant.

\label{prop:dimension-bounds}
Let $A\in\mathfrak m M_{m,n}$ be finitely determined.  Then:
\begin{enumerate}[label=\textup{(\roman*)}]
\item if $A$ is finitely $\mathcal R$-determined, then
$mn\le s$;
\item if $A$ is finitely $\mathcal G_l$-determined, then
$mn\le m^2+s$;
\item if $A$ is finitely $\mathcal G_r$-determined, then
$mn\le n^2+s$.
\end{enumerate}
In particular, when $n>m$, finite $\mathcal G_l$-determinacy implies $m(n-m)\le s$, and when $m>n$, finite $\mathcal G_r$-determinacy implies $n(m-n)\le s$.

\label{cor:icis-all-fields}
Let $K$ be an arbitrary field and let $I\subseteq R$ be proper with
$\dim \left(\frac{R}{I}\right)>0$.  Then $I$ is finitely contact determined if and only if $\frac{R}{I}$ is an ICIS.

\label{thm:stratified-jet}
Let $V=\mathbb A_K^d=\coprod_{\alpha=1}^tS_\alpha$ be a finite decomposition into smooth
locally closed $K$-subschemes.  For $A\in\mathfrak m R^d$ and $N\ge2$, there is
$B\in A+\mathfrak m^N R^d$ such that:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item $B$ is the completion of an algebraic map $F:W\to V$ from an étale
neighborhood $W\to\mathbb A_K^s$ of the origin;
\item $F$ is transverse to every $S_\alpha$ away from the distinguished point.
\end{enumerate}

Finite one-sided determinacy implies finite $\mathcal G_{lr}$-determinacy.  Theorem~\ref{thm:glr}
and Lemma~\ref{lem:rank} therefore give rank-stratum transversality away from the
origin.  Apply Proposition~\ref{prop:one-sided-criterion}.

\label{lem:deep-gauge-rigidity}
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item If $A$ is $k$-$\mathcal G_l$-determined and $V-I_n\in\mathfrak m^kM_n(R)$, then $AV\sim_{\mathcal G_l}A$, and on every rank-$r$ locus the kernel maps differ by a source automorphism.
\item Dually, if $A$ is $k$-$\mathcal G_r$-determined and $U-I_m\in\mathfrak m^kM_m(R)$, then $UA\sim_{\mathcal G_r}A$, and on every rank-$r$ locus the image maps differ by a source automorphism.
\end{enumerate}

\label{thm:one-sided-complete}
Let $A\in\mathfrak m M_{m,n}$. If $K$ is infinite, then:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item $A$ is finitely $\mathcal G_l$-determined if and only if $\dim_K\left(
\frac{M_{m,n}}
{\widetilde T_A^{\,e}(\mathcal G_l A)}
\right)<\infty$.
\item $A$ is finitely $\mathcal G_r$-determined if and only if $\dim_K\left(
\frac{M_{m,n}}
{\widetilde T_A^{\,e}(\mathcal G_r A)}
\right)<\infty$. 
\end{enumerate}
The same equivalences hold for the ordinary tangent images. Over an arbitrary field, including a finite field, the corresponding
equivalences hold in the dimension ranges of
Theorem~\ref{thm:one-sided-ranges}.

\label{cor:rank-trans}
A matrix germ is finitely $\mathcal G_{lr}$-determined exactly when, on the punctured formal
spectrum, it is transverse to every constant-rank stratum.

\label{lem:taylor}
For $f\in R$ and $Y=(Y_1,\ldots,Y_n)$ one has
\begin{equation}\label{eq:taylor}
 f(x+Y)-f(x)-\sum_{i=1}^n(\partial_i f)(x)Y_i
 \in\langle Y_1,\ldots,Y_n\rangle^2R[[Y_1,\ldots,Y_n]].
\end{equation}
This holds over an arbitrary field.

\label{lem:integrate}
Assume that $f\in\mathfrak m^2$ is isolated and suppose $z\in\mathfrak m R^n$ satisfies $\sum_i z_i\partial_i f=0$.  Then there is an automorphism $\Phi_t\in\operatorname{Aut}_{k[[t]]}k[[t,x_1,\ldots,x_n]]$ with $\Phi_0=\mathrm{id}$, tangent vector $z$ at $t=0$, and
$\Phi_t(f)=f$.

\label{thm:length}
If $d=\operatorname{Fmod}(f)$, then
\begin{equation}\label{eq:exact-length}
 p^n(d+1)=\mu(f)+n+\varepsilon_F(f).
\end{equation}
Moreover
\begin{equation}\label{eq:gamma-bound}
 \mu(f)+n\le\gamma_p(f)(d+1)
 \le\gamma_p(f)(\operatorname{Rmod}(f)+1),
 \qquad\gamma_p(f)\le p^n.
\end{equation}
In particular
\begin{equation}\label{eq:main-bound}
 \operatorname{Rmod}(f)\ge\operatorname{Fmod}(f)\ge
 \left\lceil\frac{\mu(f)+n}{p^n}\right\rceil-1.
\end{equation}

\label{lem:loewy}
For isolated $f$, we have $\mathfrak m^{B_F(f)+1}
 \subseteq\langle x_1^p,\ldots,x_n^p\rangle^{\ell_F(f)}
 \subseteq Q_F(f)R
 \subseteq\mathfrak m\operatorname{Jac}(f)$. Consequently, we get that $\eta(f)\le B_F(f)+1$.

\label{prop:Fmod-zero-criterion}
For an isolated $f\in\mathfrak m^2$, the following are equivalent:
\begin{enumerate}[label=(\roman*),leftmargin=*]
\item $\operatorname{Fmod}(f)=0$;
\item $Q_F(f)=\mathfrak n_F$;
\item $x_i^p\in\mathfrak m\operatorname{Jac}(f)$ for every $i$;
\item Frobenius on $M_f=\frac{R}{\mathfrak m\operatorname{Jac}(f)}$ kills its maximal ideal.
\end{enumerate}
If these conditions hold, then
\[
 \mathfrak m^{n(p-1)+1}\subseteq\mathfrak m\operatorname{Jac}(f),\qquad
 \mu(f)+n\le p^n,
\]
and $f$ is right $2n(p-1)$-determined.

\label{prop:susp}
With this notation, $A_F(f)\cong A_F(g)$,
$\operatorname{Fmod}(f)=\operatorname{Fmod}(g)$, $\ell_F(f)=\ell_F(g)$, and $\mu(f)=\mu(g)$.

\label{thm:uniform}
Fix $p>0$ and $D\ge0$, and let $f$ be isolated with $\operatorname{Rmod}(f)\le D$.  After splitting
off a nonsingular quadratic block, the residual germ satisfies:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item it has at most $C_{p,D}$ variables;
\item its Milnor number is at most $p^{C_{p,D}}(D+1)-C_{p,D}$;
\item its right classification radius is at most $N_{p,D}$;
\item if it is nonzero, its multiplicity is at most $p(D+1)$.
\end{enumerate}

\label{thm:finite-modular-classification}
Fix $p>0$ and $D\ge0$.  Up to nonsingular quadratic suspension, the isolated germs $f$ with
$\operatorname{Rmod}(f)\le D$ are covered by finitely many algebraic families $F_i(x,t)$, $t\in T_i$, such
that:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item $\dim T_i\le D$, the number of variables is at most $C_{p,D}$, and
$\deg_xF_i\le N_{p,D}$;
\item every stable right-equivalence class occurs;
\item each stable class occurs at only finitely many points of each $T_i$.
\end{enumerate}
The $T_i$ may be refined so that Milnor number and right modality are constant.

\label{cor:uniform-m-adic-constancy}
Fix $p>0$ and $D\ge0$.  Let $f$ be isolated with $\operatorname{Rmod}(f)\le D$ and
$h\in\mathfrak m^{\widehat N_{p,D}+1}$.  Then:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item $f+h\overset{\mathcal R}{\sim}f$ and $\operatorname{fpt}(f+h)=\operatorname{fpt}(f)$;
\item $f+h$ has the same numerical $F$-jumping spectrum as $f$;
\item for some local coordinate automorphism $\varphi$ we have that 
$\tau((f+h)^\lambda)=\varphi(\tau(f^\lambda))$ for every $\lambda\ge0$.
\end{enumerate}

\label{cor:Fjump-separation}
Any two distinct $F$-jumping numbers in $(0,1]$ arising at modality at most $D$
differ by at least $\frac{1}{Q_{p,D}^2}$.

\label{cor:test-uniform}
Let $A=\frac{R}{\langle f\rangle}$ be reduced, write $\mathfrak m_A=\frac{\mathfrak m}{\langle f\rangle}$, and assume $\operatorname{Rmod}(f)\le D$.  Then:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item the number of $F$-jumping coefficients in $[0,1]$ is at most $M_{p,D}+1$;
\item $\operatorname{length}_k\left(\frac{A}{\tau_{\mathrm{fg}}(A)}\right)\le M_{p,D}$;
\item if $E=pD+C_{p,D}(p-1)+1$, then
$\mathfrak m_A^E\subseteq\operatorname{Jac}(f)A\subseteq\tau_{\mathrm{fg}}(A)$.
\end{enumerate}
